20|      name: "bar",
21|      type: "string",
22|    }, {
23|      name: "baz",
24|      type: "string",
25|    }],
26|    option: (option, value) => {
27|      options.push({ option, value });
28|    },
29|  });
30|
31|  assertEquals(options.length, 3);
32|  assertEquals(options[0].option.name, "foo");
33|  assertEquals(options[0].value, "fooVal");
